import { __ } from '@wordpress/i18n';
import { useBlockProps, RichText, MediaUpload, MediaUploadCheck } from '@wordpress/block-editor';
import { TextControl, TextareaControl, SelectControl, Button } from '@wordpress/components';

/**
 * Same real, confirmed rung set as Content Builder's own TEXT_FS_OPTIONS
 * (see content-builder/src/constants.js) — mirrored here rather than
 * imported since there's no cross-block shared constants module yet.
 * Confirmed live on identityglobal.com/sport/: the real Intro
 * Text/Secondary Text paragraphs carry manually-applied fs-500/fs-400
 * classes, not a fixed per-block size — this is real editorial choice,
 * not a default this block can compute on its own. Includes a blank
 * "Default" option so existing content (created before this field
 * existed) keeps rendering at the block's own CSS fallback size.
 */
const TEXT_FS_OPTIONS = [
	{ label: 'Default', value: '' },
	{ label: 'fs-100', value: 'fs-100' },
	{ label: 'fs-200', value: 'fs-200' },
	{ label: 'fs-400', value: 'fs-400' },
	{ label: 'fs-500', value: 'fs-500' },
	{ label: 'fs-600', value: 'fs-600' },
	{ label: 'fs-700', value: 'fs-700' },
];
import { useSelect } from '@wordpress/data';
import { store as coreStore } from '@wordpress/core-data';
import EditorBlockShell from '../../_shared/EditorBlockShell';

/**
 * Built from About Page Header (and its siblings — Innovation Header,
 * Region Page Header, identity's Service Page Header, the header portion of
 * Culture Page Header) — see identity-global-block-spec.md's Page Header
 * entry. This first pass is built and verified against the About page
 * specifically; `title` renders as a plain multi-line H1 there (confirmed
 * live — no animated split-title markup exists in that instance's DOM).
 *
 * The block has two distinct output regions, grouped visually below to
 * match: the top header (title/intro/background), and an optional
 * secondary panel underneath it (plain text or a pull-quote, never both).
 */
export default function Edit( { attributes, setAttributes, clientId } ) {
	const {
		title,
		introText,
		introTextFontSize,
		animatedTitle,
		headerVariant,
		secondaryPanelType,
		secondaryText,
		secondaryTextFontSize,
		quote,
		quoteAuthor,
		quoteCompany,
		backgroundId,
		backgroundScope,
		overlayId,
	} = attributes;
	const blockProps = useBlockProps( { className: 'container cb-identityjs2026-editor-block' } );
	const backgroundUrl = useBackgroundUrl( backgroundId );
	// Plain Hero is just title + intro + optional parallax image (legacy CB Plain
	// Hero has no animated title, scope choice or secondary panel), so those
	// controls are hidden for it.
	const isPlain = 'plain' === headerVariant;
	// The About variant (full-height hero, ported from the legacy About Hero) is
	// likewise just title + intro + background (+ overlay image) + an optional text
	// band: no animated title, scope choice or quote panel.
	const isAbout = 'about-hero' === headerVariant;
	const isSimple = isPlain || isAbout;
	const overlayUrl = useBackgroundUrl( overlayId );

	return (
		<EditorBlockShell blockProps={ blockProps } clientId={ clientId } title="CB Page Header" textDomain="cb-identityjs2026">
			<SectionHeading>{ __( 'Header', 'cb-identityjs2026' ) }</SectionHeading>

			<SelectControl
				label={ __( 'Header Variant', 'cb-identityjs2026' ) }
				value={ headerVariant }
				options={ [
					{ label: 'Default (About)', value: 'default' },
					{ label: 'Service (e.g. FAQs)', value: 'service' },
					{ label: 'Plain Hero (dark, parallax image)', value: 'plain' },
					{ label: 'About (full-height hero)', value: 'about-hero' },
				] }
				help={ __( 'Service is a distinctly smaller/tighter real treatment (identity\'s own Service Page Header) — confirmed live on identityglobal.com/faqs/. Plain Hero reproduces the legacy CB Plain Hero: a ruled title, an intro, and an optional parallax Background image. About (full-height hero) reproduces the legacy About Hero: a full-screen hero with the title between two rules, an optional Overlay Image, and the Secondary Text as a band at the bottom. Neither has an animated title or quote panel, so those fields are hidden.', 'cb-identityjs2026' ) }
				onChange={ ( value ) => setAttributes( { headerVariant: value } ) }
			/>

			<div style={ { display: 'flex', flexWrap: 'wrap', gap: '12px' } }>
				<div style={ { flex: isSimple ? '1 1 100%' : '50 1 0%' } }>
					<TextareaControl
						label={ __( 'Title', 'cb-identityjs2026' ) }
						value={ title }
						help={ __( 'Renders as the page\'s plain <h1> — one line per row.', 'cb-identityjs2026' ) }
						onChange={ ( value ) => setAttributes( { title: value } ) }
					/>
				</div>
				{ ! isSimple && (
					<div style={ { flex: '50 1 0%' } }>
						<TextareaControl
							label={ __( 'Animated Title', 'cb-identityjs2026' ) }
							value={ animatedTitle }
							help={ __( 'Optional — renders below Title with a split-line animated treatment, not instead of it. One line per row, up to 3 lines (the reveal animation only has bar/rotation sets for 3).', 'cb-identityjs2026' ) }
							onChange={ ( value ) => setAttributes( { animatedTitle: value } ) }
						/>
					</div>
				) }
			</div>

			<div className="cb-identityjs2026-editor-field">
				<label className="cb-identityjs2026-editor-field__label">{ __( 'Intro Text', 'cb-identityjs2026' ) }</label>
				<RichText
					identifier="introText"
					tagName="div"
					multiline="p"
					className="cb-identityjs2026-editor-field__control"
					aria-label={ __( 'Intro Text', 'cb-identityjs2026' ) }
					placeholder={ __( 'Intro Text', 'cb-identityjs2026' ) }
					value={ introText }
					onChange={ ( value ) => setAttributes( { introText: value } ) }
				/>
				<p className="cb-identityjs2026-editor-field__help">{ __( 'Paragraph(s) shown under the title.', 'cb-identityjs2026' ) }</p>
			</div>

			<SelectControl
				label={ __( 'Intro Text Font Size', 'cb-identityjs2026' ) }
				value={ introTextFontSize }
				options={ TEXT_FS_OPTIONS }
				help={ __( 'Real content sets this per page (e.g. fs-500) rather than relying on one fixed size — pick to match.', 'cb-identityjs2026' ) }
				onChange={ ( value ) => setAttributes( { introTextFontSize: value } ) }
			/>

			<div className="cb-identityjs2026-editor-field">
				<label className="cb-identityjs2026-editor-field__label">{ __( 'Background', 'cb-identityjs2026' ) }</label>
				<MediaUploadCheck>
					<MediaUpload
						onSelect={ ( media ) => setAttributes( { backgroundId: media.id } ) }
						allowedTypes={ [ 'image' ] }
						value={ backgroundId }
						render={ ( { open } ) => (
							<div className="cb-identityjs2026-editor-field__control">
								{ backgroundUrl && (
									<img
										src={ backgroundUrl }
										alt=""
										style={ { maxWidth: '200px', display: 'block', marginBottom: '8px' } }
									/>
								) }
								<Button variant="secondary" onClick={ open }>
									{ backgroundUrl ? __( 'Replace Background', 'cb-identityjs2026' ) : __( 'Select Background', 'cb-identityjs2026' ) }
								</Button>
								{ backgroundUrl && (
									<Button
										variant="tertiary"
										isDestructive
										onClick={ () => setAttributes( { backgroundId: 0 } ) }
									>
										{ __( 'Remove', 'cb-identityjs2026' ) }
									</Button>
								) }
							</div>
						) }
					/>
				</MediaUploadCheck>
				<p className="cb-identityjs2026-editor-field__help">
					{ isSimple
						? __( 'Optional — scrolls with a parallax effect behind the title (no tint).', 'cb-identityjs2026' )
						: __( 'Full-bleed photo behind the whole header, with a dark tint over it.', 'cb-identityjs2026' ) }
				</p>
			</div>

			{ isAbout && (
				<div className="cb-identityjs2026-editor-field">
					<label className="cb-identityjs2026-editor-field__label">{ __( 'Overlay Image', 'cb-identityjs2026' ) }</label>
					<MediaUploadCheck>
						<MediaUpload
							onSelect={ ( media ) => setAttributes( { overlayId: media.id } ) }
							allowedTypes={ [ 'image' ] }
							value={ overlayId }
							render={ ( { open } ) => (
								<div className="cb-identityjs2026-editor-field__control">
									{ overlayUrl && <img src={ overlayUrl } alt="" style={ { maxWidth: '200px', display: 'block', marginBottom: '8px' } } /> }
									<Button variant="secondary" onClick={ open }>
										{ overlayUrl ? __( 'Replace Overlay Image', 'cb-identityjs2026' ) : __( 'Select Overlay Image', 'cb-identityjs2026' ) }
									</Button>
									{ overlayUrl && (
										<Button variant="tertiary" isDestructive onClick={ () => setAttributes( { overlayId: 0 } ) }>
											{ __( 'Remove', 'cb-identityjs2026' ) }
										</Button>
									) }
								</div>
							) }
						/>
					</MediaUploadCheck>
					<p className="cb-identityjs2026-editor-field__help">{ __( 'Optional — drawn over the background at 60% opacity.', 'cb-identityjs2026' ) }</p>
				</div>
			) }

			{ backgroundUrl && ! isSimple && (
				<SelectControl
					label={ __( 'Background Scope', 'cb-identityjs2026' ) }
					value={ backgroundScope }
					options={ [
						{ label: 'Full Header', value: 'full' },
						{ label: 'Secondary Panel Only', value: 'secondary' },
					] }
					help={ __(
						"Full Header matches About/Region/Service Page Header. Secondary Panel Only reproduces cb-policies-page's own secondary_background field, which only ever sat behind its second band, never the title — needs a Secondary Panel below to be visible.",
						'cb-identityjs2026'
					) }
					onChange={ ( value ) => setAttributes( { backgroundScope: value } ) }
				/>
			) }

			{ ! isPlain && (
				<>
					<SectionHeading>{ isAbout ? __( 'Secondary Text (bottom band)', 'cb-identityjs2026' ) : __( 'Secondary Panel', 'cb-identityjs2026' ) }</SectionHeading>

					<SelectControl
						label={ __( 'Type', 'cb-identityjs2026' ) }
						value={ secondaryPanelType }
						options={ [
							{ label: 'None', value: 'none' },
							{ label: 'Text', value: 'text' },
							...( isAbout ? [] : [ { label: 'Quote', value: 'quote' } ] ),
						] }
						help={ __( 'An optional second panel below the header — plain text, a pull-quote, or nothing.', 'cb-identityjs2026' ) }
						onChange={ ( value ) => setAttributes( { secondaryPanelType: value } ) }
					/>

					{ secondaryPanelType === 'text' && (
						<>
							<div className="cb-identityjs2026-editor-field">
								<label className="cb-identityjs2026-editor-field__label">{ __( 'Secondary Text', 'cb-identityjs2026' ) }</label>
								<RichText
									identifier="secondaryText"
									tagName="div"
									multiline="p"
									className="cb-identityjs2026-editor-field__control"
									aria-label={ __( 'Secondary Text', 'cb-identityjs2026' ) }
									placeholder={ __( 'Secondary Text', 'cb-identityjs2026' ) }
									value={ secondaryText }
									onChange={ ( value ) => setAttributes( { secondaryText: value } ) }
								/>
							</div>
							<SelectControl
								label={ __( 'Secondary Text Font Size', 'cb-identityjs2026' ) }
								value={ secondaryTextFontSize }
								options={ TEXT_FS_OPTIONS }
								help={ __( 'Real content sets this per page (e.g. fs-400) rather than relying on one fixed size — pick to match.', 'cb-identityjs2026' ) }
								onChange={ ( value ) => setAttributes( { secondaryTextFontSize: value } ) }
							/>
						</>
					) }

					{ ! isAbout && secondaryPanelType === 'quote' && (
						<>
							<TextareaControl
								label={ __( 'Quote', 'cb-identityjs2026' ) }
								value={ quote }
								onChange={ ( value ) => setAttributes( { quote: value } ) }
							/>
							<div style={ { display: 'flex', flexWrap: 'wrap', gap: '12px' } }>
								<div style={ { flex: '50 1 0%' } }>
									<TextControl
										label={ __( 'Quote Author', 'cb-identityjs2026' ) }
										value={ quoteAuthor }
										onChange={ ( value ) => setAttributes( { quoteAuthor: value } ) }
									/>
								</div>
								<div style={ { flex: '50 1 0%' } }>
									<TextControl
										label={ __( 'Quote Company', 'cb-identityjs2026' ) }
										value={ quoteCompany }
										onChange={ ( value ) => setAttributes( { quoteCompany: value } ) }
									/>
								</div>
							</div>
						</>
					) }
				</>
			) }
		</EditorBlockShell>
	);
}

/**
 * Resolves an attachment ID to its full-size URL via core-data, instead of
 * storing a separate `backgroundUrl` attribute that only gets populated
 * inside MediaUpload's own onSelect callback — that dual-attribute
 * approach broke the preview the moment backgroundId was set any other way
 * (a test script, a programmatic block insert), since backgroundUrl just
 * stayed empty. This can't go stale the same way: it's derived, not stored.
 *
 * @param {number} id Attachment ID, or 0/falsy for none.
 */
function useBackgroundUrl( id ) {
	return useSelect(
		( select ) => {
			if ( ! id ) {
				return '';
			}
			const media = select( coreStore ).getMedia( id );
			return media?.source_url || '';
		},
		[ id ]
	);
}

/**
 * A small labelled divider between this block's two output regions — the
 * top header vs. the optional secondary panel below it — so the field list
 * reads as two grouped sections instead of one flat list with no
 * indication of which fields feed which part of the output.
 *
 * Needs its own opaque background: the selected block's own highlight
 * colour (WordPress's default `is-selected` grey) shows through in the
 * gap this heading's margin creates, since — unlike the surrounding field
 * controls, which each paint their own white background/border — a bare
 * heading with just a bottom border doesn't cover the space above it.
 */
function SectionHeading( { children } ) {
	return (
		<h3
			style={ {
				position: 'relative',
				margin: 0,
				padding: '20px 0 12px',
				background: '#fff',
				borderBottom: '1px solid #ddd',
				fontSize: '11px',
				fontWeight: 700,
				letterSpacing: '0.05em',
				textTransform: 'uppercase',
				color: '#50575e',
			} }
		>
			{ children }
		</h3>
	);
}
